def find_minimal_edit(s_in, s_out):
    """Find the minimal edit between two strings"""
    # Find first position where they differ
    pos = -1
    for i, (c_in, c_out) in enumerate(zip(s_in, s_out)):
        if c_in != c_out:
            pos = i
            break

    if pos == -1:
        # Strings are identical or one is prefix of other
        if len(s_in) > len(s_out):
            return (s_in[len(s_out):], "", pos)
        elif len(s_out) > len(s_in):
            return ("", s_out[len(s_in):], pos)
        else:
            return ("", "", -1)  # No difference

    # Find the substring that needs to be replaced
    # Try to match as much as possible
    old_sub = ""
    new_sub = ""

    # Simple approach: find longest common prefix and suffix
    # and determine what's in between
    i = pos
    while i < len(s_in) and i < len(s_out) and s_in[i] == s_out[i]:
        i += 1
    old_sub = s_in[pos:i]

    j = pos
    while j < len(s_in) and j < len(s_out) and s_in[j] == s_out[j]:
        j += 1
    new_sub = s_out[pos:j]

    # If we couldn't match, just take one character
    if not old_sub:
        old_sub = s_in[pos:pos+1]
    if not new_sub:
        new_sub = s_out[pos:pos+1]

    return (old_sub, new_sub, pos)

# Analyze the changed pairs
inputs = ['juewu', 'zw', 'wk', 'dv', 'vyyj']
outputs = ['juewu', 'zw', 'wwvi', 'dv', 'vkkj']

changed_pairs = [(2, 'wk', 'wwvi'), (4, 'vyyj', 'vkkj')]

for idx, inp, outp in changed_pairs:
    old_sub, new_sub, pos = find_minimal_edit(inp, outp)
    print(f"Pair {idx}: '{inp}' -> '{outp}'")
    print(f"  Old substring: '{old_sub}', New substring: '{new_sub}', Position: {pos}")
    print()

